PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS pengaturan_desa(id INTEGER PRIMARY KEY CHECK(id=1),nama_desa TEXT DEFAULT 'NAMA DESA',kecamatan TEXT DEFAULT 'NAMA KECAMATAN',kabupaten TEXT DEFAULT 'NAMA KABUPATEN',provinsi TEXT DEFAULT 'PROVINSI',alamat TEXT DEFAULT 'Alamat Kantor Desa',kode_pos TEXT DEFAULT '',kepala_desa TEXT DEFAULT '',nip_kepala_desa TEXT DEFAULT '',logo_path TEXT DEFAULT '',stempel_path TEXT DEFAULT '',tanda_tangan_path TEXT DEFAULT '',format_nomor TEXT DEFAULT '001/{bulan}/{tahun}');
INSERT OR IGNORE INTO pengaturan_desa(id) VALUES(1);
CREATE TABLE IF NOT EXISTS pengguna(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT UNIQUE NOT NULL,password TEXT NOT NULL,nama TEXT,role TEXT DEFAULT 'Operator',aktif INTEGER DEFAULT 1);
INSERT OR IGNORE INTO pengguna(id,username,password,nama,role,aktif) VALUES(1,'admin','admin123','Administrator Desa','Admin',1);
CREATE TABLE IF NOT EXISTS penduduk(id INTEGER PRIMARY KEY AUTOINCREMENT,nik TEXT UNIQUE NOT NULL,no_kk TEXT,nama TEXT NOT NULL,tempat_lahir TEXT,tanggal_lahir TEXT,jenis_kelamin TEXT,agama TEXT,pendidikan TEXT,pekerjaan TEXT,status_perkawinan TEXT,alamat TEXT,rt TEXT,rw TEXT,desa TEXT,kecamatan TEXT,kabupaten TEXT,provinsi TEXT,status_kependudukan TEXT DEFAULT 'Tetap',aktif INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS jenis_surat(id INTEGER PRIMARY KEY AUTOINCREMENT,kode TEXT UNIQUE,nama TEXT NOT NULL,kategori TEXT DEFAULT 'Administrasi Desa',aktif INTEGER DEFAULT 1,field_json TEXT DEFAULT '[]');
CREATE TABLE IF NOT EXISTS surat(id INTEGER PRIMARY KEY AUTOINCREMENT,nomor_surat TEXT,jenis_surat_id INTEGER,penduduk_id INTEGER,tanggal_surat TEXT,keperluan TEXT,data_form TEXT DEFAULT '{}',created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(jenis_surat_id) REFERENCES jenis_surat(id),FOREIGN KEY(penduduk_id) REFERENCES penduduk(id));
CREATE TABLE IF NOT EXISTS arsip_surat(id INTEGER PRIMARY KEY AUTOINCREMENT,surat_id INTEGER,nomor_surat TEXT,jenis_surat TEXT,nik TEXT,nama_penduduk TEXT,tanggal_surat TEXT,tahun INTEGER,FOREIGN KEY(surat_id) REFERENCES surat(id));
CREATE TABLE IF NOT EXISTS template_surat(id INTEGER PRIMARY KEY AUTOINCREMENT,kode TEXT UNIQUE,nama TEXT,judul TEXT,isi TEXT,ukuran_kertas TEXT DEFAULT 'A4',margin_atas REAL DEFAULT 2,margin_bawah REAL DEFAULT 2,margin_kiri REAL DEFAULT 3,margin_kanan REAL DEFAULT 3,aktif INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS backup_log(id INTEGER PRIMARY KEY AUTOINCREMENT,file_path TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
